        {
            decision = new AccessDecision(false, "tenant-mismatch", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryValidateRequestState(
        Principal principal,
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
